    /// var output = await client.GetItemAsync(input);
    ///
    /// // Expected output:
    /// var expectedOutput = new GetItemOutput(Item: new Dictionary&lt;string, AttributeValue&gt; { { &quot;AlbumTitle&quot;, AttributeValue.FromS(&quot;Songs About Life&quot;) }, { &quot;Artist&quot;, AttributeValue.FromS(&quot;Acme Band&quot;) }, { &quot;SongTitle&quot;, AttributeValue.FromS(&quot;Happy Day&quot;) } });
