    private static DynamoDB20120810ClientConfig WithEndpoint(
        Uri endpoint,
        DynamoDB20120810ClientConfig? config
    )
    {
        ArgumentNullException.ThrowIfNull(endpoint);
        var copy = config is null
            ? new DynamoDB20120810ClientConfig()
            : new DynamoDB20120810ClientConfig(config);
        copy.Endpoint = endpoint;
        return copy;
    }

