    /// &lt;p&gt;For more information, see &lt;a href=&quot;https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/TTL.html&quot;&gt;Time To Live&lt;/a&gt; in the
    /// Amazon DynamoDB Developer Guide. &lt;/p&gt;
    /// </summary>
    /// <param name="input">
