public sealed class DynamoDB20120810ClientConfig : SmithyClientConfig
{
    public DynamoDB20120810ClientConfig() { }

    public DynamoDB20120810ClientConfig(DynamoDB20120810ClientConfig source)
        : base(source)
    {
        Region = source.Region;
        UseDualStack = source.UseDualStack;
        UseFips = source.UseFips;
        AccountId = source.AccountId;
        AccountIdEndpointMode = source.AccountIdEndpointMode;
    }

    /// <summary>
    /// The AWS region requests are sent to, such as us-east-1.
    /// </summary>
    public string? Region { get; set; }

    /// <summary>
    /// Whether to use dual-stack (IPv4 and IPv6) endpoints.
    /// </summary>
    public bool? UseDualStack { get; set; }

    /// <summary>
    /// Whether to use FIPS endpoints.
    /// </summary>
    public bool? UseFips { get; set; }

    /// <summary>
    /// The AWS account id, for account-based endpoints.
    /// </summary>
    public string? AccountId { get; set; }

    /// <summary>
    /// Whether account-based endpoints are used: preferred, required, or disabled.
    /// </summary>
    public string? AccountIdEndpointMode { get; set; }
}
